/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Library: none - Native interpolate/spring and SVG drawing for clean broadcast graphics

const { fontFamily: interFamily } = loadInter();



export type OlympicBroadcastChartProps = Record<string, any>;

const OlympicBroadcastChart: React.FC<OlympicBroadcastChartProps> = ({
  backgroundColor = "#041135",
  transparentBackground = false,
  durationInSeconds = 7,
  swimmerName = "CAMPBELL MCKEAN",
  swimmerInitials = "CM",
  eventName = "MEN 100 METER BREASTSTROKE",
  eventStage = "FINALS",
  finalsOverallTime = "59.93",
  prelimsOverallTime = "1:01.14",
  finalsColor = "#2E6BFF",
  prelimsColor = "#00D8FF",
  splits = [
    { label: "50M", finalsValue: 27.77, prelimsValue: 28.96, finalsDisplay: "27.77", prelimsDisplay: "28.96" },
    { label: "100M", finalsValue: 32.16, prelimsValue: 32.18, finalsDisplay: "32.16", prelimsDisplay: "32.18" }
  ],
  finalBestText = "NEW PERSONAL BEST"
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Timings
  const chartFadeIn = interpolate(frame, [10, 30], [0, 1], { extrapolateRight: "clamp" });

  // Compute dynamic Y-axis bounds based on data
  const allValues = splits.flatMap(sp => [sp.finalsValue, sp.prelimsValue]);
  const minVal = Math.min(...allValues, 34);
  const maxVal = Math.max(...allValues, 24);
  const yAxisMin = Math.floor(minVal / 2) * 2 - 2;
  const yAxisMax = Math.ceil(maxVal / 2) * 2;
  const numSteps = (yAxisMax - yAxisMin) / 2;
  const ySteps = Array.from({ length: Math.max(1, numSteps + 1) }, (_, i) => yAxisMin + i * 2);

  // Chart Layout Dimensions
  const ChartLeft = 350 * s;
  const ChartRight = 1450 * s;
  const ChartTop = 420 * s;
  const ChartBottom = 900 * s;

  const getY = (val: number) => {
    const range = yAxisMax - yAxisMin;
    const progress = range === 0 ? 0.5 : (val - yAxisMin) / range;
    return ChartBottom - progress * (ChartBottom - ChartTop);
  };

  const splitXs = splits.map((_, i) => {
    if (splits.length === 1) return (ChartLeft + ChartRight) / 2;
    return 500 * s + (i / (splits.length - 1)) * (850 * s);
  });

  // Prepare split animation timeline sequence
  const timeline = splits.map((split, i) => {
    const splitAppearsAt = 30 + i * 90;
    return {
      ...split,
      appearsAt: splitAppearsAt,
      drawStart: splitAppearsAt + 30,
      drawEnd: splitAppearsAt + 90,
      glowStart: splitAppearsAt + 10,
      glowEnd: splitAppearsAt + 30,
      x: splitXs[i],
      fY: getY(split.finalsValue),
      pY: getY(split.prelimsValue)
    };
  });

  const finalCalloutStart = timeline.length > 0 ? timeline[timeline.length - 1].appearsAt + 40 : 160;
  const finalCalloutOpacity = interpolate(frame, [finalCalloutStart, finalCalloutStart + 15], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const finalCalloutScale = spring({ frame: Math.max(0, frame - finalCalloutStart), fps, config: { damping: 14 } });
  
  const emphasizeStart = finalCalloutStart + 30;
  const emphasizeScale = interpolate(frame, 
    [emphasizeStart, emphasizeStart + 15, emphasizeStart + 30], 
    [1, 1.05, 1], 
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, overflow: 'hidden' }}>
      {!transparentBackground && (
        <div style={{
          position: 'absolute', width: '100%', height: '100%',
          background: `radial-gradient(circle at 50% 50%, transparent 0%, rgba(0,0,0,0.4) 100%)`,
          pointerEvents: 'none'
        }} />
      )}

      {/* Top Left Header */}
      <div style={{ position: 'absolute', left: 100 * s, top: 80 * s, opacity: chartFadeIn, display: 'flex', flexDirection: 'row', alignItems: 'center' }}>
        <div style={{ 
          width: 80 * s, height: 80 * s, borderRadius: '50%', backgroundColor: finalsColor, 
          display: 'flex', justifyContent: 'center', alignItems: 'center', 
          color: '#fff', fontSize: 36 * s, fontWeight: 'bold' 
        }}>
          {swimmerInitials}
        </div>
        <div style={{ marginLeft: 30 * s, display: 'flex', flexDirection: 'column' }}>
          <div style={{ color: '#fff', fontSize: 56 * s, fontWeight: 900, letterSpacing: '1px', lineHeight: 1 }}>
            {swimmerName}
          </div>
          <div style={{ display: 'flex', flexDirection: 'row', alignItems: 'center', marginTop: 12 * s }}>
            <div style={{ color: '#A0C0FF', fontSize: 24 * s, fontWeight: 'bold', textTransform: 'uppercase' }}>
              {eventName} |
            </div>
            <div style={{ marginLeft: 12 * s, backgroundColor: '#FFD700', padding: `${4 * s}px ${12 * s}px`, borderRadius: 6 * s, color: '#000', fontSize: 20 * s, fontWeight: 900 }}>
              {eventStage}
            </div>
          </div>
        </div>
      </div>

      {/* Primary Legend (Top) */}
      <div style={{ position: 'absolute', left: 210 * s, top: 240 * s, opacity: chartFadeIn, display: 'flex', flexDirection: 'row' }}>
        <div style={{ display: 'flex', flexDirection: 'column', marginRight: 80 * s }}>
          <div style={{ display: 'flex', flexDirection: 'row', alignItems: 'center' }}>
            <div style={{ width: 24 * s, height: 24 * s, borderRadius: '50%', backgroundColor: finalsColor, marginRight: 12 * s }} />
            <div style={{ color: '#fff', fontSize: 24 * s, fontWeight: 'bold' }}>FINALS</div>
          </div>
          <div style={{ color: '#fff', fontSize: 44 * s, fontWeight: 900, marginTop: 4 * s, lineHeight: 1 }}>
            {finalsOverallTime}
          </div>
        </div>
        
        <div style={{ display: 'flex', flexDirection: 'column' }}>
          <div style={{ display: 'flex', flexDirection: 'row', alignItems: 'center' }}>
            <div style={{ width: 24 * s, height: 24 * s, borderRadius: 6 * s, backgroundColor: prelimsColor, marginRight: 12 * s }} />
            <div style={{ color: '#fff', fontSize: 24 * s, fontWeight: 'bold' }}>PRELIMS</div>
          </div>
          <div style={{ color: '#fff', fontSize: 44 * s, fontWeight: 900, marginTop: 4 * s, lineHeight: 1 }}>
            {prelimsOverallTime}
          </div>
        </div>
      </div>

      {/* Olympic Rings (Recreated cleanly) */}
      <svg style={{ position: 'absolute', right: 80 * s, top: 60 * s, opacity: chartFadeIn }} width={160 * s} height={80 * s} viewBox="0 0 160 80">
        <g stroke="#ffffff" strokeWidth="3" fill="none" transform="translate(15, 10) scale(1.2)">
          <circle cx="20" cy="20" r="14" />
          <circle cx="52" cy="20" r="14" />
          <circle cx="84" cy="20" r="14" />
          <circle cx="36" cy="34" r="14" />
          <circle cx="68" cy="34" r="14" />
        </g>
      </svg>

      {/* Main Chart Canvas */}
      <svg width={width} height={height} style={{ position: 'absolute', top: 0, left: 0, overflow: 'visible' }}>
        {/* Y Axis Grid */}
        {ySteps.map((val, i) => {
          const y = getY(val);
          return (
            <g key={`ygrid-${i}`} opacity={chartFadeIn} style={{ transition: "none" }}>
              <text x={ChartLeft - 20 * s} y={y + 2 * s} fill="#A0AABF" fontSize={24 * s} textAnchor="end" alignmentBaseline="middle" style={{ transition: "none" }}>
                {val}s
              </text>
              <line x1={ChartLeft + 10 * s} x2={ChartRight} y1={y} y2={y} stroke="#ffffff" strokeOpacity={0.15} strokeWidth={1.5 * s} style={{ transition: "none" }} />
            </g>
          );
        })}

        {/* Drawn Line Segments */}
        {timeline.map((split, i) => {
          if (i === timeline.length - 1) return null;
          const nextSplit = timeline[i + 1];
          const t = interpolate(frame, [split.drawStart, split.drawEnd], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
          
          const curFX = split.x + (nextSplit.x - split.x) * t;
          const curFY = split.fY + (nextSplit.fY - split.fY) * t;
          const fD = `M ${split.x} ${split.fY} L ${curFX} ${curFY}`;
          
          const curPX = split.x + (nextSplit.x - split.x) * t;
          const curPY = split.pY + (nextSplit.pY - split.pY) * t;
          const pD = `M ${split.x} ${split.pY} L ${curPX} ${curPY}`;
          
          return (
            <g key={`segment-${i}`} opacity={t > 0 ? 1 : 0} style={{ transition: "none" }}>
              <path d={pD} fill="none" stroke={prelimsColor} strokeWidth={4 * s} strokeDasharray={`${10 * s} ${10 * s}`} style={{ transition: "none" }} />
              <path d={fD} fill="none" stroke={finalsColor} strokeWidth={6 * s} style={{ transition: "none" }} />
            </g>
          );
        })}

        {/* Splits (Nodes, vertical dashes, labels) */}
        {timeline.map((split, i) => {
          const scale = spring({ frame: Math.max(0, frame - split.appearsAt), fps, config: { damping: 12 } });
          const visible = frame >= split.appearsAt;
          
          const glowProgress = interpolate(frame, [split.glowStart, split.glowEnd], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
          const glowOp = Math.sin(glowProgress * Math.PI) * 0.6;
          const glowScale = 1 + glowProgress * 1.5;
          
          const isFinish = split.label.includes("100M");
          const boxWidth = (isFinish ? 90 : 120) * s;
          const labelText = isFinish ? "FINISH" : `${split.label} SPLIT`;
          const nodeBg = backgroundColor;
          
          return (
            <g key={`split-${i}`} opacity={visible ? 1 : 0} style={{ transition: "none" }}>
              {/* Vertical Dashed Line */}
              <line 
                x1={split.x} y1={ChartBottom + 20 * s} 
                x2={split.x} y2={ChartTop - 40 * s} 
                stroke="#ffffff" strokeOpacity={0.3} strokeWidth={2 * s} strokeDasharray={`${6 * s} ${6 * s}`} 
                style={{ transition: "none" }}
              />
              
              {/* Top Label */}
              <g transform={`translate(${split.x}, ${ChartTop - 60 * s}) scale(${scale})`} style={{ transition: "none" }}>
                <rect x={-boxWidth/2} y={-16 * s} width={boxWidth} height={32 * s} rx={6 * s} fill="#2E6BFF" style={{ transition: "none" }} />
                <text x={0} y={2 * s} fill="#ffffff" fontSize={16 * s} fontWeight="bold" textAnchor="middle" alignmentBaseline="middle" style={{ transition: "none" }}>
                  {labelText}
                </text>
              </g>
              
              {/* Bottom Label */}
              <g transform={`translate(${split.x}, ${ChartBottom + 50 * s}) scale(${scale})`} style={{ transition: "none" }}>
                <text x={0} y={0} fill="#ffffff" fontSize={24 * s} fontWeight="bold" textAnchor="middle" alignmentBaseline="middle" style={{ transition: "none" }}>
                  {split.label}
                </text>
              </g>
              
              {/* Prelims Node & Value */}
              <g transform={`translate(${split.x}, ${split.pY}) scale(${scale})`} style={{ transition: "none" }}>
                <rect x={-14 * s * glowScale} y={-14 * s * glowScale} width={28 * s * glowScale} height={28 * s * glowScale} rx={6 * s * glowScale} fill={prelimsColor} opacity={glowOp} style={{ transition: "none" }} />
                <rect x={-12 * s} y={-12 * s} width={24 * s} height={24 * s} rx={6 * s} fill={nodeBg} stroke={prelimsColor} strokeWidth={4 * s} style={{ transition: "none" }} />
                <text x={-24 * s} y={2 * s} fill={prelimsColor} fontSize={24 * s} fontWeight="bold" textAnchor="end" alignmentBaseline="middle" style={{ transition: "none" }}>
                  {split.prelimsDisplay}
                </text>
              </g>
              
              {/* Finals Node & Value */}
              <g transform={`translate(${split.x}, ${split.fY}) scale(${scale})`} style={{ transition: "none" }}>
                <circle r={12 * s * glowScale} fill={finalsColor} opacity={glowOp} style={{ transition: "none" }} />
                <circle r={10 * s} fill={nodeBg} stroke={finalsColor} strokeWidth={4 * s} style={{ transition: "none" }} />
                <text x={-24 * s} y={2 * s} fill={finalsColor} fontSize={24 * s} fontWeight="bold" textAnchor="end" alignmentBaseline="middle" style={{ transition: "none" }}>
                  {split.finalsDisplay}
                </text>
              </g>
            </g>
          );
        })}
      </svg>

      {/* Finals Time Emphasis Callout (Right Edge) */}
      <div style={{ 
        position: 'absolute', right: 140 * s, top: '50%', marginTop: -80 * s,
        opacity: finalCalloutOpacity, display: 'flex', flexDirection: 'column', alignItems: 'center', width: 300 * s
      }}>
        <div style={{ transform: `scale(${finalCalloutScale})`, display: 'flex', flexDirection: 'column', alignItems: 'center', width: '100%' }}>
          <div style={{ color: '#ffffff', fontSize: 24 * s, fontWeight: 'bold', letterSpacing: '2px' }}>
            FINALS TIME
          </div>
          <div style={{ 
            color: '#ffffff', fontSize: 110 * s, fontWeight: 900, 
            marginTop: -10 * s, marginBottom: 10 * s,
            transform: `scale(${emphasizeScale})`, transformOrigin: 'center center'
          }}>
            {finalsOverallTime}
          </div>
          <div style={{ width: '100%', height: 2 * s, backgroundColor: finalsColor, marginBottom: 12 * s }} />
          <div style={{ color: prelimsColor, fontSize: 20 * s, fontWeight: 'bold', letterSpacing: '1px' }}>
            {finalBestText}
          </div>
        </div>
      </div>

      {/* Secondary Legend (Bottom Center) */}
      <div style={{ position: 'absolute', bottom: 50 * s, width: '100%', display: 'flex', justifyContent: 'center', opacity: chartFadeIn, flexDirection: 'row', alignItems: 'center' }}>
        <div style={{ display: 'flex', alignItems: 'center', marginRight: 60 * s }}>
          <div style={{ width: 40 * s, height: 4 * s, backgroundColor: finalsColor, marginRight: 16 * s }} />
          <div style={{ color: '#fff', fontSize: 20 * s, fontWeight: 'bold' }}>FINALS</div>
        </div>
        <div style={{ display: 'flex', alignItems: 'center' }}>
          <div style={{ width: 40 * s, height: 0, borderTop: `${4 * s}px dashed ${prelimsColor}`, marginRight: 16 * s }} />
          <div style={{ color: '#fff', fontSize: 20 * s, fontWeight: 'bold' }}>PRELIMS</div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default OlympicBroadcastChart;